{"implementation": "def solve(case):
    payload = case['payload']
    text = payload['text']
    passes = payload['passes']
    max_rounds = payload['max_rounds']
    trace = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old = p['old']
            new = p['new']
            pos = text.find(old)
            if pos != -1:
                text = text[:pos] + new + text[pos+len(old):]
                trace.append(p['name'])
                changed = True
        if not changed:
            return {'artifact': text, 'trace': trace, 'fixed_point': True}
    return {'artifact': text, 'trace': trace, 'fixed_point': False}"}
